import base64, os, subprocess, ast
os.makedirs("/content/fly", exist_ok=True)
code = base64.b64decode("").decode("utf-8")
assert "" not in code or True
ast.parse(code)
open("/content/fly/build_graph.py", "w", encoding="utf-8").write(code)
print("wrote /content/fly/build_graph.py %d bytes" % len(code))
print("data files:", sorted(os.listdir("/content/fly/data")))
chk = subprocess.run("pgrep -f build_graph.py | head -1", shell=True, capture_output=True, text=True).stdout.strip()
if chk:
    print("ALREADY_RUNNING pid=", chk)
else:
    subprocess.Popen("nohup python -u /content/fly/build_graph.py > /content/fly/build.log 2>&1 &",
                     shell=True, executable="/bin/bash")
    print("LAUNCHED")
